import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"6 轮压测和 2 个 P0：AI 写的代码怎么验收","description":"","frontmatter":{"title":"6 轮压测和 2 个 P0：AI 写的代码怎么验收"},"headers":[],"relativePath":"md/ai-code/acceptance.md","filePath":"md/ai-code/acceptance.md","lastUpdated":1795434315000}'),r={name:"md/ai-code/acceptance.md"};function n(s,t,c,i,p,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="_6-轮压测和-2-个-p0-ai-写的代码怎么验收" tabindex="-1">6 轮压测和 2 个 P0：AI 写的代码怎么验收 <a class="header-anchor" href="#_6-轮压测和-2-个-p0-ai-写的代码怎么验收" aria-label="Permalink to &quot;6 轮压测和 2 个 P0：AI 写的代码怎么验收&quot;">​</a></h1><p>AI 交付代码时说&quot;已实现、已自测通过&quot;，这句话的信息量约等于零。它能编译、能跑通一次正常流程，这和&quot;能扛住真实流量&quot;是两件完全不同的事，而它不会告诉你边界在哪。</p><p>这个秒杀项目，我是用压测和故障演练做完验收的。过程里我自己犯了三个错，比代码的缺陷更值得记。</p><h2 id="先说压测做了什么" tabindex="-1">先说压测做了什么 <a class="header-anchor" href="#先说压测做了什么" aria-label="Permalink to &quot;先说压测做了什么&quot;">​</a></h2><p>k6 打同一个秒杀接口，库存前置到 Redis，靠 Lua 原子扣减。每轮结束都做三方对账：<strong>数据库订单数 / Redis 剩余库存 / 一致性核对表</strong>。</p><table tabindex="0"><thead><tr><th>库存</th><th>VU</th><th>请求</th><th>成功</th><th>吞吐</th><th>P95</th></tr></thead><tbody><tr><td>1000</td><td>200</td><td>10000</td><td>1000</td><td>2884/s</td><td>136ms</td></tr><tr><td>2000</td><td>500</td><td>20000</td><td>2000</td><td>3186/s</td><td>290ms</td></tr><tr><td>2000</td><td>1000</td><td>20000</td><td>2000</td><td>4249/s</td><td>342ms</td></tr><tr><td>30000</td><td>2000</td><td>30000</td><td>30000</td><td>1881/s</td><td>1250ms</td></tr></tbody></table><p>零超卖每一轮都成立，<code>reconcile</code> 表全程 0 条。这项是<strong>唯一只能靠压测证明、不能靠代码审查证明</strong>的东西：Lua 脚本里 <code>decr</code> 前判库存的写法，看起来可能有并发窗口，只有 3 万个并发请求打下去、最后对账是 30000 才叫证明。</p><p>在拒绝路径（已售罄、重复下单、被限流）上，吞吐能到 4249 req/s；全成功路径只有 1881 req/s，P95 1.25 秒 —— 后者才是真实容量的答案。</p><h2 id="我自己犯的三个错" tabindex="-1">我自己犯的三个错 <a class="header-anchor" href="#我自己犯的三个错" aria-label="Permalink to &quot;我自己犯的三个错&quot;">​</a></h2><p>这部分比缺陷清单更有用，因为 AI 全程没有提醒过其中任何一个。</p><table tabindex="0"><thead><tr><th>错误</th><th>我以为是</th><th>实际是</th></tr></thead><tbody><tr><td>伪 IP 生成</td><td>2000 个虚拟用户分散成 2000 个 IP</td><td><code>uid * 1000000</code> 的高位恒定，只落 200 个 IP，22497 个请求被限流打掉</td></tr><tr><td>故障演练</td><td>Redis 数据丢了，返回 503 符合预期</td><td><code>shutdown nosave</code> 后 brew 的 launchd 自动拉起并加载了 RDB，数据根本没丢</td></tr><tr><td>修 500 错误</td><td>捕获 <code>RedisConnectionFailureException</code> 就够了</td><td>实际抛的是 <code>QueryTimeoutException</code>（500ms 超时伪装成超时异常），捕获无效</td></tr></tbody></table><p>三个错误是同一个错误：<strong>没真正验证，就以为验证过了</strong>。</p><p>第一个错最隐蔽 —— 压测结果&quot;看起来正常&quot;（有成功有失败有 409），只有对账数字对不上才暴露。第二个错最危险 —— 我甚至在报告里写下了结论，是后来复现不了才回头查的。</p><p>这就是人工验收的价值所在：AI 会生成一个自洽的解释，<strong>它不会怀疑自己的验证方法</strong>。</p><h2 id="两个-p0" tabindex="-1">两个 P0 <a class="header-anchor" href="#两个-p0" aria-label="Permalink to &quot;两个 P0&quot;">​</a></h2><p>修的时候我踩了一个坑，值得单独说。</p><p><strong>P0-001，Redis 不可达返回 500。</strong> 第一版修复凭经验捕获 <code>RedisConnectionFailureException</code>，重测还是 500。看堆栈才发现是 <code>org.springframework.dao.QueryTimeoutException</code>。最后改成捕获父类 <code>DataAccessException</code> → 503。<strong>异常类型不要猜，去读堆栈。</strong></p><p><strong>P0-002，缓存丢失后永久 503。</strong> 加自动重建，看起来简单，但有三个必须守住的约束，错一个就出更大的问题：</p><ol><li>库存用 <code>SETNX</code> 写，<strong>绝不覆盖</strong>实时值 —— 否则会把已经扣掉的库存&quot;还回去&quot;，直接超卖</li><li>库存 = 总库存 − 已成交订单 − <strong>未解决异常单</strong>。异常单是已预扣未落库的，漏掉它就多卖</li><li>幂等集合必须从订单表回填 —— 不回填的话，缓存一丢，同一用户可以重复下单，等于绕过全部幂等防线</li></ol><p>第 2 条是这类自愈逻辑最常见的坑：<strong>从数据库&quot;重新算一遍&quot;听着安全，但算错了就是在制造超卖</strong>。</p><p>修复后回归：库存 1000、10000 请求 → 成功 <strong>1000</strong>、DB <strong>1000</strong>、Redis <strong>0</strong>、<code>reconcile</code> <strong>0</strong>，3727 req/s，P95 119ms。修复没有引入退化。</p><h2 id="性能画像" tabindex="-1">性能画像 <a class="header-anchor" href="#性能画像" aria-label="Permalink to &quot;性能画像&quot;">​</a></h2><p>应用内埋点显示，Lua 扣减平均 <strong>11.77ms</strong>，占总延迟约 1%。真正的瓶颈是 Hikari 30 连接的写库队列。</p><p>秒杀的性能问题几乎从不在&quot;扣减&quot;这一步 —— 那一步是原子的、内存级的。瓶颈在扣完之后异步落库的那一段，以及连接池大小。要优化应该动这里，而不是把 Lua 写得更花哨。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>AI 把写代码的成本压到了接近零，验收成本就成了新的瓶颈，而且这个成本只能人出：定义清楚的失败语义、设计能骗过自己的压测、在&quot;看起来正常&quot;的数据里找出对不上的那个数字。</p><p>代码是它写的，但&quot;能扛&quot;这件事，得自己证明。</p><p>需求那一侧怎么写的：<a href="./requirement.html">把需求写给 AI</a>。</p>',28)])])}const g=d(r,[["render",n]]);export{u as __pageData,g as default};
